update setmeal
category_id = #{categoryId}, name = #{name}, price = #{price}, status = #{status}, description = #{description}, image = #{image}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select s.id, s.category_id, s.name, s.price, s.status, s.description, s.image, s.create_time, s.update_time, s.create_user, s.update_user, c.name as category_name from setmeal s left join category c on s.category_id = c.id
and s.name like concat('%', #{name}, '%') and s.status = #{status} and s.category_id = #{categoryId}
order by s.create_time desc

select * from dish d
left join setmeal_dish sd on d.id = sd.dish_id
where sd.setmeal_id = #{setmealId}

select * from setmeal

     and name like concat('%',#{name},'%') 
     and category_id = #{categoryId} 
     and status = #{status}
